'use client';

// Sliders for the body path and the mood map's slider alternative.
// Generated by the shadcn/ui CLI on Radix Slider (arrow keys, Home/End,
// screen-reader values) and adapted: a bigger thumb that is easy to grab, a
// 48px tall touch area, and an optional spoken value ("Energy 2") so a
// screen reader hears words, not just a number.
import * as React from 'react';
import { cn } from '@/lib/utils';
import { Slider as SliderPrimitive } from 'radix-ui';

type SliderProps = React.ComponentProps<typeof SliderPrimitive.Root> & {
  thumbLabel?: string;
  thumbLabelledBy?: string;
  valueText?: (value: number) => string;
};

function Slider({ className, defaultValue, value, min = 0, max = 100, thumbLabel, thumbLabelledBy, valueText, ...props }: SliderProps) {
  const values = React.useMemo(
    () => (Array.isArray(value) ? value : Array.isArray(defaultValue) ? defaultValue : [min]),
    [value, defaultValue, min],
  );

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn('relative flex min-h-12 w-full touch-none items-center select-none data-disabled:opacity-50', className)}
      {...props}
    >
      <SliderPrimitive.Track data-slot="slider-track" className="relative h-2 grow overflow-hidden rounded-full bg-surface-2">
        <SliderPrimitive.Range data-slot="slider-range" className="absolute h-full bg-primary/40" />
      </SliderPrimitive.Track>
      {values.map((v, index) => (
        <SliderPrimitive.Thumb
          data-slot="slider-thumb"
          key={index}
          aria-label={thumbLabel}
          aria-labelledby={thumbLabelledBy}
          aria-valuetext={valueText?.(v)}
          className="block size-7 shrink-0 rounded-full border-2 border-primary bg-surface shadow-sm"
        />
      ))}
    </SliderPrimitive.Root>
  );
}

export { Slider };
